assert len(model["recommended_outline"]) == 8
assert len(model["routing_aliases"]) == 14

anchor_ids = {row["id"] for row in fact["anchors"]}
for row in model["expected_question_patterns"]:
    assert set(row["required_anchor_ids"]) <= anchor_ids
outline_union: set[str] = set()
for row in model["recommended_outline"]:
    refs = set(row["anchor_refs"])
    assert refs <= anchor_ids
    outline_union.update(refs)
assert outline_union == anchor_ids

assert importance["schema_version"] == "topic_pack.topic_importance.v1"
assert importance["difficulty"] == "THEORY_CORE"
assert importance["selection_importance"] == "CORE_MUST_PREPARE"
assert importance["question_type"] == "PRINCIPLE_INTERPRETATION"
assert len(importance["high_band_unlock_conditions"]) >= 12

fatal_ids = {row["id"] for row in fact["fatal_wrong_claims"]}
for required in {
