print("TOPIC_PACK_SCHEMA_VALIDATION=PASS")
print(f"ANCHORS={len(fact['anchors'])}")
print(f"FATALS={len(fact['fatal_wrong_claims'])}")
print(f"MAJORS={len(profile['major_checks'])}")
print(f"ALIASES={len(model['routing_aliases'])}")

