validate_lane_ownership() {
    local base_ref merge_base rel
    if git rev-parse --verify --quiet "${REMOTE}/main" >/dev/null; then
        base_ref="${REMOTE}/main"
    elif git rev-parse --verify --quiet main >/dev/null; then
        base_ref="main"
    else
        fail "origin/main and local main are unavailable for Lane ownership audit"
        return 1
    fi

    merge_base="$(git merge-base HEAD "$base_ref")" || {
        fail "cannot compute merge-base against $base_ref"
        return 1
    }

    printf 'OWNERSHIP_BASE_REF=%s\n' "$base_ref"
    printf 'OWNERSHIP_MERGE_BASE=%s\n' "$merge_base"
    printf 'LANE_BRANCH_CHANGED_PATHS_BEGIN\n'

    while IFS= read -r rel; do
        [ -n "$rel" ] || continue
        printf '%s\n' "$rel"
        if ! is_lane_branch_path "$rel"; then
            fail "Lane branch path is outside Lane C ownership: $rel"
        fi
        case "$rel" in
            rubrics/generated/*)
                fail "Lane branch modifies forbidden generated path: $rel"
                ;;
            *.py)
                case "$rel" in
                    scripts/test_sis_sil_safety_software_topic.py|\
                    scripts/test_historian_mes_it_ot_data_integration_topic.py|\
                    scripts/test_industrial_ai_ml_model_lifecycle_topic.py|\
                    "$TEST_REL")
                        ;;
                    *)
                        fail "Lane branch modifies production or non-focused Python: $rel"
                        ;;
                esac
                ;;
        esac
    done < <(git diff --name-only "$merge_base"..HEAD)

    printf 'LANE_BRANCH_CHANGED_PATHS_END\n'

    if git diff --name-only "$merge_base"..HEAD -- rubrics/generated/ | grep -q .; then
        fail "rubrics/generated/** changed on Lane C branch"
    else
        pass "rubrics/generated/** unchanged on Lane C branch"
    fi

    [ "$failure_count" -eq 0 ]
}

text_quality_validation() {
    python3 - "$REPO_DIR" "${TARGETS[@]}" <<'PY_TEXT'
from pathlib import Path
import sys

root = Path(sys.argv[1])
for rel in sys.argv[2:]:
    path = root / rel
    raw = path.read_bytes()
    raw.decode("utf-8")
    if not raw.endswith(b"\n"):
        raise SystemExit(f"missing final newline: {rel}")
    for number, line in enumerate(raw.decode("utf-8").splitlines(), start=1):
        if line.endswith((" ", "\t")):
            raise SystemExit(f"trailing whitespace: {rel}:{number}")
print("TEXT_QUALITY_VALIDATION=PASS")
PY_TEXT
}

validate_exact_topic_commit() {
    local sw_number="$1"
    local subject="$2"
    local array_name="$3"
    local commit actual_subject
    local -a expected_paths actual_paths

    commit="$(find_topic_commit "$subject")"
    [ -n "$commit" ] || {
        fail "$sw_number commit is missing: $subject"
        return 1
    }
    git merge-base --is-ancestor "$commit" HEAD >/dev/null 2>&1 || {
        fail "$sw_number commit is not an ancestor of HEAD"
        return 1
    }

    eval 'expected_paths=("${'"$array_name"'[@]}")'
    mapfile -t expected_paths < <(printf '%s\n' "${expected_paths[@]}" | LC_ALL=C sort)
    mapfile -t actual_paths < <(git diff-tree --no-commit-id --name-only -r "$commit" | LC_ALL=C sort)

    actual_subject="$(git log -1 --pretty=%s "$commit")"
    [ "$actual_subject" = "$subject" ] || {
        fail "$sw_number commit subject mismatch"
        return 1
    }

    if [ "${#expected_paths[@]}" -ne "${#actual_paths[@]}" ]; then
        fail "$sw_number commit path count mismatch"
        return 1
    fi

    local index
    for index in "${!expected_paths[@]}"; do
        if [ "${expected_paths[$index]}" != "${actual_paths[$index]}" ]; then
            fail "$sw_number commit path mismatch: expected=${expected_paths[$index]} actual=${actual_paths[$index]}"
            return 1
        fi
    done

    printf 'TOPIC_COMMIT=%s|%s|%s\n' "$sw_number" "$commit" "$subject"
    pass "$sw_number has one exact Topic commit"
}

