push_lane_once() {
    local local_head remote_head remote_after
    local_head="$(git rev-parse HEAD)"

    if ! git fetch "$REMOTE" "$LANE_BRANCH"; then
        fail "failed to fetch remote Lane C branch before push"
        return 1
    fi

    remote_head="$(git rev-parse "refs/remotes/${REMOTE}/${LANE_BRANCH}" 2>/dev/null || true)"
    printf 'LOCAL_LANE_HEAD=%s\n' "$local_head"
    printf 'REMOTE_LANE_HEAD_BEFORE_PUSH=%s\n' "${remote_head:-NONE}"

    if [ -n "$remote_head" ]; then
        if ! git merge-base --is-ancestor "$remote_head" "$local_head"; then
            fail "remote Lane C branch contains commits not present in local HEAD; refusing non-fast-forward push"
            return 1
        fi
    fi

    if git push "$REMOTE" "HEAD:refs/heads/${LANE_BRANCH}"; then
        push_performed=1
        pass "pushed Lane C branch once without force"
    else
        fail "Lane C branch push failed"
        return 1
    fi

    remote_after="$(git ls-remote --heads "$REMOTE" "refs/heads/${LANE_BRANCH}" | awk '{print $1}')"
    printf 'REMOTE_LANE_HEAD_AFTER_PUSH=%s\n' "${remote_after:-NONE}"

    if [ "$remote_after" != "$local_head" ]; then
        fail "remote Lane C head does not equal local HEAD after push"
        return 1
    fi
    pass "remote Lane C head equals local HEAD after push"
}

