        "FOCUSED_TESTS_PASS=true" \
        "WORKING_TREE_CLEAN=true" \
        "GENERATED_BANK_CHANGED=false" \
        "LANE_A_B_FILES_CHANGED=false" \
        "GENERATED_REBUILD_RUN=false" \
        "FULL_ROUTER_REGRESSION_RUN=false" \
        "CROSS_TOPIC_DUPLICATE_CHECK_RUN=false" \
        "VALIDATE_ALL_RUN=false" \
        "RELEASE_VALIDATION_RUN=false" \
        "CONTAINER_SMOKE_RUN=false"
    pass "Lane C final source-only validation"

    set_stage "LANE_C_SINGLE_PUSH" "INTEGRATION_HANDOFF"
    section "9. push Lane C branch once"

    push_lane_once || return 1

    if [ "$push_performed" -ne 1 ]; then
        fail "expected one Lane C push was not performed"
        return 1
    fi

    CURRENT_STAGE="LANE_C_COMPLETE_AND_PUSHED"
    NEXT_STAGE="INTEGRATION_LLM_MERGE_AND_FULL_VALIDATION"
    LANE_PROGRESS="4/4"
    section "10. Lane C completion report"

    printf '%s\n' \
        "LANE=${LANE}" \
        "LANE_BRANCH=${LANE_BRANCH}" \
        "SW_NUMBER=SW-13" \
        "TOPIC_ID=${TOPIC_ID}" \
        "COMMIT_HASH=$(git rev-parse HEAD)" \
        "COMMIT_SUBJECT=$(git log -1 --pretty=%s)" \
        "VALIDATION_RESULT=PASS" \
        "LANE_VALIDATION_RESULT=PASS" \
        "JSON_SYNTAX=PASS" \
        "TOPIC_PACK_SCHEMA=PASS" \
        "SW13_FOCUSED_TEST=PASS" \
        "ALL_FOUR_FOCUSED_TESTS=PASS" \
        "TOPIC_COMMITS_SEPARATE=true" \
        "GIT_DIFF_CHECK=PASS" \
        "LANE_C_OWNERSHIP=PASS" \
        "WORKING_TREE_CLEAN=true" \
        "GENERATED_BANK_CHANGED=false" \
        "EXTERNAL_LLM_VALIDATION_RUN=false" \
        "PUSH_PERFORMED=true" \
        "PUSH_REMOTE=${REMOTE}" \
        "PUSH_BRANCH=${LANE_BRANCH}" \
        "MAIN_PUSH_PERFORMED=false" \
        "NEXT_ACTION=INTEGRATION_LLM_MERGE_LANE_C_AND_RUN_FULL_VALIDATION" \
        "LANE_PROGRESS=${LANE_PROGRESS}"
    print_context

    return 0
}

main || final_rc=$?

(return "$final_rc" 2>/dev/null) || [ "$final_rc" -eq 0 ]
